use super::*;
use crate::gpui_shell::copy_feedback::CopyFeedback;
use crate::i18n::Message;

pub(super) struct PivPane {
    result: Option<Result<Option<String>, String>>,
    task: Option<Task<()>>,
    abort: Option<tokio::task::AbortHandle>,
    copied: Entity<CopyFeedback>,
    _copied: Subscription,
}

impl PivPane {
    pub(super) fn new(cx: &mut Context<Self>) -> Self {
        let copied = cx.new(|_| CopyFeedback::new());
        let subscription = cx.observe(&copied, |_, _, cx| cx.notify());
        Self { result: None, task: None, abort: None, copied, _copied: subscription }
    }

    fn prepare(&mut self, cx: &mut Context<Self>) {
        if self.abort.is_some() {
            return;
        }
        let runtime = match crate::ssh_session::runtime() {
            Ok(runtime) => runtime,
            Err(error) => {
                self.result = Some(Err(error.to_string()));
                cx.notify();
                return;
            },
        };
        let language = crate::gpui_shell::config::ui_language(cx);
        let task = runtime.spawn(crate::ssh_session::piv::prepare(
            language.text(Message::PivPin).to_owned(),
        ));
        self.result = None;
        self.copied.update(cx, |feedback, cx| feedback.clear(cx));
        self.abort = Some(task.abort_handle());
        self.task = Some(cx.spawn(async move |this, cx| {
            let result = match task.await {
                Ok(result) => result.map_err(|error| error.to_string()),
                Err(error) => Err(error.to_string()),
            };
            let _ = this.update(cx, |this, cx| {
                this.abort = None;
                this.result = Some(result);
                cx.notify();
            });
        }));
        cx.notify();
    }

    fn cancel(&mut self, cx: &mut Context<Self>) {
        if let Some(abort) = self.abort.take() {
            abort.abort();
        }
        self.task = None;
        self.result = Some(Ok(None));
        cx.notify();
    }
}

impl Drop for PivPane {
    fn drop(&mut self) {
        if let Some(abort) = self.abort.take() {
            abort.abort();
        }
    }
}

impl Render for PivPane {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let language = crate::gpui_shell::config::ui_language(cx);
        let busy = self.abort.is_some();
        let supported = crate::ssh_session::piv::SUPPORTED;
        let notice = match &self.result {
            Some(Ok(Some(_))) => language.text(Message::PivReady).to_owned(),
            Some(Ok(None)) => language.text(Message::PivCancelled).to_owned(),
            Some(Err(error)) => language.format(Message::PivFailed, &[("error", error)]),
            None if busy => language.text(Message::PivLoading).to_owned(),
            None => String::new(),
        };
        v_flex().id("piv-settings").gap_3()
            .child(div().text_sm().font_medium().child(language.text(Message::PivTitle)))
            .child(div().text_xs().text_color(cx.theme().muted_foreground)
                .child(language.text(if supported { Message::PivHelp } else { Message::PivUnsupported })))
            .child(h_flex().gap_2()
                .child(Button::new("piv-prepare").label(language.text(Message::PivPrepare))
                    .disabled(busy || !supported)
                    .on_click(cx.listener(|this, _, _, cx| this.prepare(cx))))
                .when(busy, |row| row.child(
                    Button::new("piv-cancel").label(language.text(Message::CommonCancel))
                        .on_click(cx.listener(|this, _, _, cx| this.cancel(cx))),
                ))
                .when(matches!(self.result, Some(Ok(Some(_)))), |row| row.child(
                    Button::new("piv-copy").label(language.text(if self.copied.read(cx).is_copied() {
                        Message::PivCopied
                    } else {
                        Message::PivCopy
                    })).on_click(cx.listener(|this, _, _, cx| {
                        if let Some(Ok(Some(keys))) = &this.result {
                            cx.write_to_clipboard(gpui::ClipboardItem::new_string(keys.clone()));
                            this.copied.update(cx, |feedback, cx| feedback.mark_copied(cx));
                        }
                    })),
                )))
            .when(!notice.is_empty(), |body| body.child(div().text_xs().child(notice)))
    }
}

