use std::path::PathBuf;
use std::process::Stdio;
use std::time::Duration;

use russh::keys::agent::{AgentIdentity, client::AgentClient};
use russh::keys::ssh_key::PublicKey;

use super::{ClientSession, SessionError, lifecycle};
use crate::i18n::{Message, UiLanguage};

pub(crate) const SUPPORTED: bool = cfg!(unix);
type Agent = AgentClient<Box<dyn russh::keys::agent::client::AgentStream + Send + Unpin>>;

fn message(id: Message) -> &'static str {
    UiLanguage::EnUs.text(id)
}

async fn connect() -> Result<Agent, SessionError> {
    #[cfg(unix)]
    {
        Ok(tokio::time::timeout(Duration::from_secs(10), AgentClient::connect_env()).await??.dynamic())
    }
    #[cfg(not(unix))]
    {
        Err(message(Message::PivUnsupported).into())
    }
}

async fn provider() -> Result<PathBuf, SessionError> {
    for path in [
        "/usr/local/lib/libykcs11.dylib",
        "/opt/homebrew/lib/libykcs11.dylib",
        "/usr/lib/x86_64-linux-gnu/libykcs11.so",
        "/usr/lib/aarch64-linux-gnu/libykcs11.so",
        "/usr/lib64/libykcs11.so",
        "/usr/lib/libykcs11.so",
        "/usr/local/lib/libykcs11.so",
    ] {
        if tokio::fs::metadata(path).await.is_ok_and(|metadata| metadata.is_file()) {
            return Ok(path.into());
        }
    }
    Err(message(Message::PivProviderMissing).into())
}

fn parse_keys(text: &str) -> Result<Vec<PublicKey>, SessionError> {
    let keys = text.lines().filter(|line| !line.trim().is_empty())
        .map(PublicKey::from_openssh).collect::<Result<Vec<_>, _>>()?;
    if keys.is_empty() {
        return Err(message(Message::PivNoKeys).into());
    }
    Ok(keys)
}

async fn public_keys() -> Result<(PathBuf, Vec<PublicKey>), SessionError> {
    if !SUPPORTED {
        return Err(message(Message::PivUnsupported).into());
    }
    let provider = provider().await?;
    let output = tokio::time::timeout(
        Duration::from_secs(15),
        tokio::process::Command::new("ssh-keygen")
            .arg("-D").arg(&provider)
            .stdin(Stdio::null()).kill_on_drop(true).output(),
    ).await??;
    if !output.status.success() {
        return Err(format!("{}: {}", message(Message::PivNoKeys), String::from_utf8_lossy(&output.stderr).trim()).into());
    }
    Ok((provider, parse_keys(std::str::from_utf8(&output.stdout)?)?))
}

fn matching(identities: Vec<AgentIdentity>, keys: &[PublicKey]) -> Vec<AgentIdentity> {
    identities.into_iter().filter(|identity| {
        keys.iter().any(|key| key.key_data() == identity.public_key().key_data())
    }).collect()
}

pub(crate) async fn prepare(pin_label: String) -> Result<Option<String>, SessionError> {
    let (provider, keys) = public_keys().await?;
    let mut agent = connect().await?;
    let identities = tokio::time::timeout(Duration::from_secs(10), agent.request_identities()).await??;
    if matching(identities, &keys).is_empty() {
        let Some((pin, _)) = crate::ssh_prompt::secret(pin_label, false).await? else {
            return Ok(None);
        };
        // The PIN goes only to the existing local agent, never to argv or storage.
        tokio::time::timeout(Duration::from_secs(30), agent.add_smartcard_key(
            provider.to_str().ok_or("Invalid YKCS11 path")?, &pin, &[],
        )).await??;
    }
    let identities = tokio::time::timeout(Duration::from_secs(10), agent.request_identities()).await??;
    let keys = matching(identities, &keys);
    if keys.is_empty() {
        return Err(message(Message::PivLoadRequired).into());
    }
    let text = keys.iter().map(|key| key.public_key().to_openssh())
        .collect::<Result<Vec<_>, _>>()?.join("
");
    Ok(Some(text))
}

pub(super) async fn authenticate(session: &mut ClientSession, user: &str) -> Result<(), SessionError> {
    let (_, keys) = public_keys().await?;
    let mut agent = connect().await?;
    let identities = tokio::time::timeout(Duration::from_secs(10), agent.request_identities()).await??;
    let identities = matching(identities, &keys);
    if identities.is_empty() {
        return Err(message(Message::PivLoadRequired).into());
    }
    for identity in identities {
        let hash = super::rsa_hash_for(session, identity.public_key().algorithm().is_rsa()).await;
        let result = match identity {
            AgentIdentity::PublicKey { key, .. } => lifecycle::authentication(
                "PIV signature", session.authenticate_publickey_with(user, key, hash, &mut agent),
            ).await?,
            AgentIdentity::Certificate { certificate, .. } => lifecycle::authentication(
                "PIV signature", session.authenticate_certificate_with(user, certificate, hash, &mut agent),
            ).await?,
        };
        if result.success() {
            return Ok(());
        }
    }
    Err(message(Message::PivRejected).into())
}

#[cfg(test)]
mod tests {
    use super::*;
    use russh::keys::ssh_key::{Algorithm, PrivateKey};

    #[test]
    fn piv_public_keys_parse_and_exclude_other_agent_identities() {
        let hardware = PrivateKey::random(&mut rand::rng(), Algorithm::Ed25519).unwrap();
        let software = PrivateKey::random(&mut rand::rng(), Algorithm::Ed25519).unwrap();
        let text = hardware.public_key().to_openssh().unwrap();
        let keys = parse_keys(&format!("
{text}
")).unwrap();
        let identities = vec![software.public_key().clone().into(), hardware.public_key().clone().into()];
        let selected = matching(identities, &keys);
        assert_eq!(selected.len(), 1);
        assert_eq!(selected[0].public_key().key_data(), hardware.public_key().key_data());
        assert!(parse_keys("").is_err());
        assert!(parse_keys("not an SSH public key").is_err());
    }
}
